  "success": true,
  "message": "Sự kiện Dunvex đã được tiếp nhận và xử lý an toàn!",
  "timestamp": "{{ $now.toISO() }}"
}

parameters.jsCode:
const body = $input.first().json.body || $input.first().json;
const eventType = body.eventType || body.type || 'generic';
const botToken = (body.botToken || '').trim();
const chatId = (body.chatId || body.telegramGroupChatId || body.telegramChatId || '').trim();
const data = body.data || body;
const rawMsg = body.message || '';

if (!botToken || !chatId) return [];

const nowStr = new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });
function formatCurrency(val) {
  const n = Number(String(val || 0).replace(/[^0-9.-]/g, '')) || 0;
  return new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' }).format(n);
}

let formattedText = '';

// 1. Chuyển vào Thùng rác (Xoá mềm)
if (eventType === 'trash_moved') {
  const typeLabel = data.collection === 'orders' ? 'Đơn hàng' : (data.collection === 'customers' ? 'Khách hàng' : (data.collection === 'products' ? 'Sản phẩm' : (data.collection || 'Dữ liệu')));
  formattedText = `🗑️ <b>ĐÃ CHUYỂN VÀO THÙNG RÁC</b>\n\n` +
    `📁 <b>Loại dữ liệu:</b> <b>${typeLabel}</b>\n` +
    `🏷️ <b>Tên / Mã:</b> <b>${data.title || data.docId || 'Chi tiết'}</b>\n` +
    `👤 <b>Người xoá:</b> <b>${data.deletedBy || data.userName || 'Nhân viên'}</b>\n` +
    `🕒 <b>Thời gian:</b> ${data.time || nowStr}\n\n` +
    `⏳ <i>Dữ liệu sẽ tự động bị xoá vĩnh viễn sau 5 ngày nếu không được khôi phục.</i>`;

// 2. Khôi phục từ Thùng rác (Restore)
} else if (eventType === 'trash_restore') {
  const typeLabel = data.collection === 'orders' ? 'Đơn hàng' : (data.collection === 'customers' ? 'Khách hàng' : (data.collection === 'products' ? 'Sản phẩm' : (data.collection || 'Dữ liệu')));
  formattedText = `♻️ <b>KHÔI PHỤC DỮ LIỆU TỪ THÙNG RÁC</b>\n\n` +
    `📁 <b>Loại dữ liệu:</b> <b>${typeLabel}</b>\n` +
    `🏷️ <b>Tên / Mã:</b> <b>${data.title || data.docId || 'Chi tiết'}</b>\n` +
    `👤 <b>Người khôi phục:</b> <b>${data.restoredBy || data.userName || 'Admin'}</b>\n` +
    `🕒 <b>Thời gian:</b> ${data.time || nowStr}\n\n` +
    `✅ <i>Dữ liệu đã được khôi phục và đưa trở lại hoạt động bình thường.</i>`;

// 3. Tự động xoá vĩnh viễn thùng rác quá 5 ngày
} else if (eventType === 'trash_auto_purge') {
  let listItems = '';
  if (Array.isArray(data.items) && data.items.length > 0) {
    listItems = data.items.slice(0, 10).map(it => `  • [${it.collection}] <b>${it.title || it.id}</b>`).join('\n');
    if (data.items.length > 10) listItems += `\n  <i>... và ${data.items.length - 10} mục khác</i>`;
  }
  formattedText = `🔥 <b>TỰ ĐỘNG XOÁ VĨNH VIỄN THÙNG RÁC (> 5 NGÀY)</b>\n\n` +
    `🗑️ <b>Số lượng đã xoá:</b> <b>${data.purgedCount || 0} bản ghi</b>\n` +
    (listItems ? `\n📋 <b>Chi tiết dữ liệu hết hạn:</b>\n${listItems}\n\n` : '\n') +
    `🕒 <b>Thời gian thực hiện:</b> ${nowStr}\n` +
    `🛡️ <i>Hệ thống tự động dọn dẹp định kỳ để bảo vệ bộ nhớ.</i>`;

// 4. Chấm công
} else if (eventType === 'attendance') {
  const actionStr = data.action === 'checkout' ? '🚪 RA CA (CHECK-OUT)' : '🏢 VÀO CA (CHECK-IN)';
  const icon = data.action === 'checkout' ? '👋' : '⏰';
  formattedText = `${icon} <b>THÔNG BÁO CHẤM CÔNG - ${actionStr}</b>\n\n` +
    `👤 <b>Nhân viên:</b> <b>${data.userName || 'Nhân viên'}</b>\n` +
    `📧 <b>Email:</b> <code>${data.userEmail || '---'}</code>\n` +
    `🕒 <b>Thời gian:</b> ${data.time || nowStr}\n` +
    (data.distance != null ? `📏 <b>Khoảng cách:</b> <b>${data.distance} mét</b> ${data.distance > 200 ? '⚠️' : '✅'}\n` : '') +
    (data.location ? `📍 <b>Tọa độ:</b> <code>${data.location.lat?.toFixed(5)}, ${data.location.lng?.toFixed(5)}</code>\n` : '') +
    (data.status ? `📊 <b>Trạng thái:</b> ${data.status === 'Đúng giờ' ? '🟢 Đúng giờ' : '🟡 ' + data.status}\n` : '') +
    `⚡ <i>Ghi nhận tự động từ Dunvex Build.</i>`;

// 5. Đi công trình / giao hàng
} else if (eventType === 'site_checkin') {
  formattedText = `📍 <b>CHECK-IN CÔNG TRÌNH / GIAO HÀNG</b>\n\n` +
    `👤 <b>Nhân viên:</b> <b>${data.userName || 'Nhân viên'}</b>\n` +
    `🏗️ <b>Khách hàng/Công trình:</b> <b>${data.customerName || data.siteName || 'Công trình'}</b>\n` +
    `🕒 <b>Thời gian:</b> ${data.time || nowStr}\n` +
    (data.distance != null ? `📏 <b>Khoảng cách:</b> <b>${data.distance} mét</b>\n` : '') +
    (data.location ? `🗺️ <b>GPS:</b> <a href="https://www.google.com/maps/search/?api=1&query=${data.location.lat},${data.location.lng}">Xem bản đồ</a>\n` : '') +
    (data.imageUrl ? `📸 <b>Ảnh hiện trường:</b> <a href="${data.imageUrl}">Xem ảnh</a>\n` : '') +
    (data.note ? `📝 <b>Ghi chú:</b> <i>${data.note}</i>\n` : '');

// 6. Thu nợ
} else if (eventType === 'debt_payment') {
  formattedText = `💰 <b>THU NỢ KHÁCH HÀNG</b>\n\n` +
    `👤 <b>Khách hàng:</b> <b>${data.customerName || 'Khách hàng'}</b>\n` +
    `💵 <b>Số tiền:</b> <b>${formatCurrency(data.amount)}</b>\n` +
    `💳 <b>Hình thức:</b> ${data.paymentMethod || 'Tiền mặt / Chuyển khoản'}\n` +
    (data.remainingDebt != null ? `📉 <b>Dư nợ còn lại:</b> <b>${formatCurrency(data.remainingDebt)}</b>\n` : '') +
    `👨‍💼 <b>Người thu:</b> ${data.collectorName || data.user || 'Nhân viên'}\n` +
    `🕒 <b>Thời gian:</b> ${data.time || nowStr}`;

// 7. Đơn nghỉ phép
} else if (eventType === 'leave_request') {
  const reqType = data.requestType === 'leave' ? '🏖️ NGHỈ PHÉP' : '⏰ XIN ĐI MUỘN';
  formattedText = `📝 <b>ĐƠN ĐĂNG KÝ ${reqType}</b>\n\n` +
    `👤 <b>Nhân viên:</b> <b>${data.userName || 'Nhân viên'}</b>\n` +
    `📅 <b>Ngày:</b> <b>${Array.isArray(data.dates) ? data.dates.join(', ') : (data.dates || data.date || 'Hôm nay')}</b>\n` +
    `💬 <b>Lý do:</b> <i>${data.note || data.reason || 'Bận việc riêng'}</i>\n` +
    `🕒 <b>Thời gian:</b> ${data.time || nowStr}`;

// 8. Đơn hàng
} else if (eventType === 'order') {
  formattedText = `🛒 <b>CẬP NHẬT ĐƠN HÀNG</b>\n\n` +
    `👤 <b>Khách hàng:</b> <b>${data.customerName || 'Khách hàng'}</b>\n` +
    `💰 <b>Tổng tiền:</b> <b>${formatCurrency(data.totalAmount || data.amount)}</b>\n` +
    `📦 <b>Trạng thái:</b> <b>${data.status || 'Đơn chốt'}</b>\n` +
    `🕒 <b>Thời gian:</b> ${data.time || nowStr}`;
} else {
  formattedText = rawMsg || `🔔 <b>THÔNG BÁO DUNVEX</b>\n\n${JSON.stringify(data)}`;
}

return [{
  json: {
    botToken,
    chatId,
    text: formattedText
  }
}];

