}

parameters.jsCode:
const body = $input.first().json.body || $input.first().json;
let rawName = (body.customerName || body.name || '').trim().replace(/\s+/g, ' ');
let rawPhone = String(body.customerPhone || body.phone || '').trim().replace(/\D/g, '');
if (rawPhone.startsWith('84') && rawPhone.length > 9) rawPhone = '0' + rawPhone.slice(2);

let rawItems = body.items || body.products || body.line_items || [];
if (typeof rawItems === 'string') { try { rawItems = JSON.parse(rawItems); } catch(e) { rawItems = []; } }
if (!Array.isArray(rawItems) && typeof rawItems === 'object') rawItems = [rawItems];

const cleanedItems = rawItems.map((item, idx) => ({
  productId: item.productId || item.id || '',
  productName: (item.productName || item.name || item.title || `Sản phẩm ${idx + 1}`).trim(),
  qty: Math.max(1, Number(String(item.qty || item.quantity || 1).replace(/[^0-9.-]/g, '')) || 1),
  price: Number(String(item.price || item.unitPrice || 0).replace(/[^0-9.-]/g, '')) || 0,
  unit: item.unit || 'Cái',
  variant: item.variant || '',
  imageUrl: item.imageUrl || item.image || ''
}));

return [{
  json: {
    apiKey: body.apiKey || body.dunvexApiKey || '',
    customerName: rawName || 'Khách hàng mới',
    customerPhone: rawPhone,
    customerEmail: (body.customerEmail || body.email || '').toLowerCase().trim(),
    customerAddress: body.customerAddress || body.address || '',
    note: body.note || body.customerNote || 'Đơn hàng tự động qua n8n',
    shippingFee: Number(String(body.shippingFee || 0).replace(/[^0-9.-]/g, '')) || 0,
    paidAmount: Number(String(body.paidAmount || 0).replace(/[^0-9.-]/g, '')) || 0,
    items: cleanedItems,
    deliveryLocation: body.deliveryLocation || null,
    rawDeliveryLocation: body.rawDeliveryLocation || ''
  }
}];

const input = $('5.1 [AI Super Admin] Webhook Nhận Lệnh').first().json;
const body = input.body || input;
const command = (body.message || body.command || '').toLowerCase();
const currentConfig = $input.first().json.data || $input.first().json || {};

let updatePayload = {};
let reply = '';

if (command.includes('bảo trì')) {
  const enable = !command.includes('tắt') && !command.includes('mở');
  updatePayload = { maintenance_mode: enable };
  reply = enable ? '⛔ ĐÃ BẬT BẢO TRÌ TOÀN TRANG!' : '✅ ĐÃ TẮT BẢO TRÌ!';
} else if (command.includes('khoá tạo đơn')) {
  updatePayload = { lock_free_orders: true };
  reply = '🔒 ĐÃ KHOÁ TẠO ĐƠN CHO TÀI KHOẢN FREE!';
} else if (command.includes('mở tạo đơn')) {
  updatePayload = { lock_free_orders: false };
  reply = '🔓 ĐÃ MỞ TẠO ĐƠN CHO TÀI KHOẢN FREE!';
} else {
  reply = `📊 TRẠNG THÁI NEXUS CONTROL:\n` +
    `• Bảo trì: ${currentConfig.maintenance_mode ? '🔴 BẬT' : '🟢 TẮT'}\n` +
    `• Khoá đơn Free: ${currentConfig.lock_free_orders ? '🔒 KHOÁ' : '🟢 MỞ'}\n` +
    `• Khoá nợ Free: ${currentConfig.lock_free_debts ? '🔒 KHOÁ' : '🟢 MỞ'}`;
}

return [{
  json: {
    updatePayload,
    reply,
    shouldUpdate: Object.keys(updatePayload).length > 0
  }
}];
